import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/OUTPUT.md","filePath":"manual-en/OUTPUT.md","lastUpdated":1785684581000}'),r={name:"manual-en/OUTPUT.md"};function n(p,e,l,c,d,i){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h3 id="_17-17-output" tabindex="-1">17.17 OUTPUT <a class="header-anchor" href="#_17-17-output" aria-label="Permalink to &quot;17.17 OUTPUT&quot;">​</a></h3><pre><code>OUTPUT MODIFY
       /SELECT TABLES
       /TABLECELLS SELECT = [ class... ]
                   FORMAT = fmt_spec.
</code></pre><blockquote><p><strong>Please note:</strong> In the above synopsis the characters ‘[’ and ‘]’ are literals. They must appear in the syntax to be interpreted.</p></blockquote><p><code>OUTPUT</code> changes the appearance of the tables in which results are printed. In particular, it can be used to set the format and precision to which results are displayed.</p><p>After running this command, the default table appearance parameters will have been modified and each new output table generated uses the new parameters.</p><p>Following <code>/TABLECELLS SELECT =</code> a list of cell classes must appear, enclosed in square brackets. This list determines the classes of values should be selected for modification. Each class can be:</p><p>RESIDUAL</p><p>Residual values. Default: <code>F40.2</code>.</p><p>CORRELATION</p><p>Correlations. Default: <code>F40.3</code>.</p><p>PERCENT</p><p>Percentages. Default: <code>PCT40.1</code>.</p><p>SIGNIFICANCE</p><p>Significance of tests (p-values). Default: <code>F40.3</code>.</p><p>COUNT</p><p>Counts or sums of weights. For a weighted data set, the default is the weight variable’s print format. For an unweighted data set, the default is F40.0.</p><p>For most other numeric values that appear in tables, <code>SET FORMAT</code> may be used to specify the format (see <a href="./SET#SET-FORMAT">SET FORMAT</a>).</p><p>The value of fmt_spec must be a valid output format (see <a href="./Input-and-Output-Formats">Input and Output Formats</a>). Note that not all possible formats are meaningful for all classes.</p>`,18)])])}const T=a(r,[["render",n]]);export{h as __pageData,T as default};
